MATCH (s:Storage)
WHERE 
  // 至少有一个支持的 InstanceTypeFamily 下存在 vcpu > 16 的 InstanceType
  EXISTS {
    MATCH (s)-[:SUPPORTS]->(itf:InstanceTypeFamily)-[:CONTAINS]->(i:InstanceType)
    WHERE size(i.vcpu) > 0 AND i.vcpu =~ '^[0-9]+$' AND toInteger(i.vcpu) > 16
  }
  AND
  // 且不存在任何支持的 InstanceTypeFamily 下存在 vcpu <= 16 的 InstanceType
  NOT EXISTS {
    MATCH (s)-[:SUPPORTS]->(itf2:InstanceTypeFamily)-[:CONTAINS]->(i2:InstanceType)
    WHERE size(i2.vcpu) > 0 AND i2.vcpu =~ '^[0-9]+$' AND toInteger(i2.vcpu) <= 16
  }
RETURN s

// 查询：是否存在任何路径将 Instance 与 Region 关联？（直接或通过 Zone）
// 若结果为空 → Instance 与 Region 无关联 → 跨地域绑定无模型基础 → 不支持
MATCH (i:Instance)
WHERE NOT EXISTS {
  MATCH (i)<-[]-(:RefundPolicy)<-[]-(:Region)
} AND NOT EXISTS {
  MATCH (i)<-[]-(:RefundPolicy)<-[]-(:TimePeriod)-[]->(:ProtectionPeriod)
}
// 但注意：RefundPolicy 也不连 Region！Schema 中 RefundPolicy 无出边到 Region。
// 实际上：整个 Schema 中，**没有任何关系连接 Instance 到 Region 或 Zone**
// 所以最简、最准确的查询是检查 Instance 是否有任意出边（它没有），并确认 Region 无法到达 Instance（除 RefundPolicy 外无路径）
// 因此，我们直接查询：是否存在 Instance 与 Region 的路径（无论方向）？
// 使用双向遍历（因为 Instance 只有入边，Region 只有出边）
MATCH path = (:Region)-[*1..3]-(:Instance)
RETURN count(path) AS cross_region_binding_possible
